// Service for income-related API calls

function getAuthHeaders(): Record<string, string> {
  const token = localStorage.getItem('authToken');
  return token ? { Authorization: `Bearer ${token}` } : {};
}

export async function fetchCategories() {
  const response = await fetch('/api/Category', { headers: getAuthHeaders() });
  if (!response.ok) throw new Error('Failed to fetch categories');
  return response.json();
}

export async function fetchItems() {
  const response = await fetch('/api/Item', { headers: getAuthHeaders() });
  if (!response.ok) throw new Error('Failed to fetch items');
  return response.json();
}

export async function fetchLastIncome() {
  const response = await fetch('/api/Income/last', { headers: getAuthHeaders() });
  if (!response.ok) throw new Error('Failed to fetch last income');
  return response.json();
}

export async function fetchIncomes() {
  const response = await fetch('/api/Income', { headers: getAuthHeaders() });
  if (!response.ok) throw new Error('Failed to fetch incomes');
  return response.json();
}

export async function saveIncome(formData: FormData, isEditMode: boolean, id?: number) {
  const url = isEditMode && id ? `/api/Income/${id}` : '/api/Income';
  const method = isEditMode ? 'PUT' : 'POST';
  const response = await fetch(url, {
    method,
    headers: {
      ...getAuthHeaders(),
    },
    body: formData,
  });
  if (response.status === 200 || response.status === 201) {
    return response.json();
  } else {
    const errorData = await response.json();
    throw new Error(errorData.message || `Failed to ${isEditMode ? 'update' : 'create'} income entry`);
  }
} 